import pandas as pd
import numpy as np

# Load data
df = pd.read_csv("chunks_csv/moran_local_2021_crime.csv")
adj = pd.read_csv(ADJACENCY_PATH)

# Prepare borough list and indices
boroughs = df['borough'].tolist()
n = len(boroughs)
idx = {b: i for i, b in enumerate(boroughs)}

# Build symmetric adjacency
neighbors = {b: set() for b in boroughs}
for _, row in adj.iterrows():
    b, nbr = row['borough'], row['neighbor']
    if b in neighbors:
        neighbors[b].add(nbr)
    else:
        neighbors[b] = {nbr}
    if nbr in neighbors:
        neighbors[nbr].add(b)
    else:
        neighbors[nbr] = {b}

# Convert neighbors to index lists
nbr_idx = {idx[b]: [idx[n] for n in neighbors[b] if n in idx] for b in boroughs}

# Values and deviations
x = df['Crime_value'].values
x_bar = x.mean()
z = x - x_bar
m2 = np.sum(z**2) / n

# Compute observed local Moran's I and lagged z
I_obs = np.zeros(n)
lag_z = np.zeros(n)
for i in range(n):
    ws = nbr_idx[i]
    lag_z[i] = np.sum(z[ws])
    I_obs[i] = z[i] * lag_z[i] / m2

# Permutation test parameters
np.random.seed(0)
n_perm = 500

# Counters for p-values
count = np.zeros(n)

# Permutation
for _ in range(n_perm):
    z_perm = np.random.permutation(z)
    for i in range(n):
        ws = nbr_idx[i]
        I_perm = z[i] * np.sum(z_perm[ws]) / m2
        if I_obs[i] >= 0:
            if I_perm >= I_obs[i]:
                count[i] += 1
        else:
            if I_perm <= I_obs[i]:
                count[i] += 1

p_vals = count / n_perm

# Identify hot and cold spots
alpha = 0.05
hot = []
cold = []
for i, b in enumerate(boroughs):
    if z[i] > 0 and lag_z[i] > 0 and I_obs[i] >= 0 and p_vals[i] < alpha:
        hot.append((b, I_obs[i]))
    if z[i] < 0 and lag_z[i] < 0 and I_obs[i] < 0 and p_vals[i] < alpha:
        cold.append((b, I_obs[i]))

# Prepare final answer
if not hot and not cold:
    print("FINAL ANSWER: none")
else:
    entries = []
    for b, val in hot:
        entries.append(f"{b} (HH, statistical method={val:.4f})")
    for b, val in cold:
        entries.append(f"{b} (LL, statistical method={val:.4f})")
    print("FINAL ANSWER: " + ", ".join(entries))
